96: /**
97:  * Runtime side of a hole: meshes from the scene builder plus the Rapier colliders,
98:  * kinematic movers and hazard volumes that the same descriptors imply.
99:  */
100: export class HoleRuntime {
101:   readonly group: THREE.Group;
102: 
103:   private readonly scene: HoleSceneResult;
104:   private readonly bodies: RAPIER.RigidBody[] = [];
105:   private readonly movers: Mover[] = [];
106:   private readonly surfaces: SurfacePatch[] = [];
107:   private readonly hazards: HazardPatch[] = [];
108:   private readonly tmpVector = new THREE.Vector3();
109:   private readonly tmpQuaternion = new THREE.Quaternion();
110:   private elapsed = 0;
111: 
112:   constructor(
113:     private readonly physics: PhysicsWorld,
114:     readonly hole: Hole,
115:     builder: HoleSceneBuilder,
116:   ) {
117:     this.scene = builder.build(hole);
118:     this.group = this.scene.group;
119:     for (const surface of hole.surfaces) this.addSurface(surface);
120:     for (const obstacle of hole.obstacles) this.addObstacle(obstacle);
121:   }
122: 
123:   get moverCount(): number {
124:     return this.movers.length;
125:   }
126: 
127:   /** Advances kinematic obstacles and keeps their meshes in sync with the bodies. */
128:   update(dt: number): void {
129:     this.elapsed += Math.max(0, dt);
130:     for (const mover of this.movers) {
131:       if (mover.motion.kind === 'rotate') {
132:         const angle = (mover.motion.phase ?? 0) + this.elapsed * mover.motion.speed;
133:         this.tmpQuaternion.setFromAxisAngle(mover.axis, angle).multiply(mover.baseRotation);
134:         mover.body.setNextKinematicRotation({
135:           x: this.tmpQuaternion.x,
136:           y: this.tmpQuaternion.y,
137:           z: this.tmpQuaternion.z,
138:           w: this.tmpQuaternion.w,
139:         });
140:         mover.object?.quaternion.copy(this.tmpQuaternion);
141:         continue;
142:       }
143:       const phase = this.elapsed * mover.motion.speed + (mover.motion.phase ?? 0);
144:       const offset = Math.sin(phase) * (mover.motion.distance ?? 1);
145:       this.tmpVector.copy(mover.axis).multiplyScalar(offset).add(mover.base);
146:       mover.body.setNextKinematicTranslation({ x: this.tmpVector.x, y: this.tmpVector.y, z: this.tmpVector.z });
147:       mover.object?.position.copy(this.tmpVector);
148:     }
149:   }
150: 
151:   /** Rolling deceleration of the surface under the ball, or a harsh value off the course. */
152:   decelerationAt(position: Vec3): number {
153:     let best: SurfacePatch | undefined;
154:     for (const patch of this.surfaces) {
155:       if (!contains(patch, position.x, position.z)) continue;
156:       if (patch.top > position.y + SURFACE_REACH) continue;
157:       if (!best || patch.top > best.top) best = patch;
158:     }
159:     return best?.deceleration ?? OFF_SURFACE_DECELERATION;
160:   }
161: 
162:   hazardAt(position: Vec3): HazardObstacle | undefined {
163:     for (const patch of this.hazards) {
164:       if (!contains(patch, position.x, position.z)) continue;
165:       if (position.y <= patch.top + HAZARD_DEPTH_MARGIN) return patch.obstacle;
166:     }
167:     return undefined;
168:   }
169: 
170:   dispose(): void {
171:     for (const body of this.bodies) this.physics.world.removeRigidBody(body);
172:     this.bodies.length = 0;
173:     this.movers.length = 0;
174:     this.surfaces.length = 0;
175:     this.hazards.length = 0;
176:     this.group.removeFromParent();
177:     this.scene.dispose();
178:   }
179: 
180:   private addSurface(surface: SurfaceDescriptor): void {
181:     const size = scaledSize(surface.size, surface.transform);
182:     const position = surface.transform.position;
183:     const properties = resolveSurface(surface);
184:     const rotation = rotationOf(surface.transform);
185:     let half = new THREE.Vector3(size.x / 2, size.y / 2, size.z / 2);
186: 
187:     // A ramp descriptor means \"rise size.y over size.z\": tilt a slab and match the mesh to it.
188:     if (surface.shape === 'ramp' && !surface.transform.rotation && size.z > 0.01) {
189:       const length = Math.hypot(size.y, size.z);
190:       rotation.setFromAxisAngle(new THREE.Vector3(1, 0, 0), -Math.atan2(size.y, size.z));
191:       half = new THREE.Vector3(size.x / 2, RAMP_THICKNESS / 2, length / 2);
192:       const mesh = this.group.getObjectByName(surface.id);
193:       if (mesh) {
194:         mesh.quaternion.copy(rotation);
195:         mesh.scale.set(size.x, RAMP_THICKNESS, length);
196:       }
197:     }
198: 
199:     const body = this.physics.world.createRigidBody(
200:       RAPIER.RigidBodyDesc.fixed()
201:         .setTranslation(position.x, position.y, position.z)
202:         .setRotation({ x: rotation.x, y: rotation.y, z: rotation.z, w: rotation.w }),
203:     );
204:     const collider =
205:       surface.shape === 'cylinder'
206:         ? RAPIER.ColliderDesc.cylinder(half.y, Math.max(half.x, half.z))
207:         : RAPIER.ColliderDesc.cuboid(half.x, half.y, half.z);
208:     this.physics.world.createCollider(
209:       collider
210:         .setFriction(properties.friction)
211:         .setRestitution(properties.restitution)
212:         .setCollisionGroups(COURSE_GROUPS),
213:       body,
214:     );
215:     this.bodies.push(body);
216: 
217:     const base = DECELERATION[surface.material] ?? DECELERATION.green;
218:     const deceleration =
219:       surface.friction === undefined ? base : base * clamp(surface.friction / 0.6, 0.35, 3);
220:     this.surfaces.push({ ...areaOf(position, size), deceleration });
221:   }
222: 
223:   private addObstacle(obstacle: ObstacleDescriptor): void {
224:     if (obstacle.enabled === false) return;
225:     const size = scaledSize(obstacle.size, obstacle.transform);
226:     const position = obstacle.transform.position;
227: 
228:     if (isHazard(obstacle)) {
229:       this.hazards.push({ ...areaOf(position, size), obstacle });
230:       return;
231:     }
232: 
233:     const rotation = rotationOf(obstacle.transform);
234:     const half = new THREE.Vector3(size.x / 2, size.y / 2, size.z / 2);
235:     const moving = isMoving(obstacle);
236:     const descriptor = moving ? RAPIER.RigidBodyDesc.kinematicPositionBased() : RAPIER.RigidBodyDesc.fixed();
237:     const body = this.physics.world.createRigidBody(
238:       descriptor
239:         .setTranslation(position.x, position.y, position.z)
240:         .setRotation({ x: rotation.x, y: rotation.y, z: rotation.z, w: rotation.w }),
241:     );
242:     const override = 'restitution' in obstacle ? obstacle.restitution : undefined;
243:     const restitution =
244:       typeof override === 'number'
245:         ? override
246:         : obstacle.type === 'bumper'
247:           ? BUMPER_RESTITUTION
248:           : DEFAULT_OBSTACLE_RESTITUTION;
249:     const collider =
250:       obstacle.type === 'pillar'
251:         ? RAPIER.ColliderDesc.cylinder(half.y, Math.max(half.x, half.z))
252:         : RAPIER.ColliderDesc.cuboid(half.x, half.y, half.z);
253:     this.physics.world.createCollider(
254:       collider
255:         .setFriction(OBSTACLE_FRICTION)
256:         .setRestitution(restitution)
257:         .setCollisionGroups(OBSTACLE_GROUPS),
258:       body,
259:     );
260:     this.bodies.push(body);
261: 
262:     if (!moving) return;
263:     const axis = new THREE.Vector3(obstacle.motion.axis.x, obstacle.motion.axis.y, obstacle.motion.axis.z);
264:     if (axis.lengthSq() < 1e-8) axis.set(0, 1, 0);
265:     else axis.normalize();
266:     this.movers.push({
267:       body,
268:       object: this.group.getObjectByName(obstacle.id),
269:       base: new THREE.Vector3(position.x, position.y, position.z),
270:       axis,
271:       baseRotation: rotation.clone(),
272:       motion: obstacle.motion,
273:     });
274:   }
275: }
